# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::RelayOutboxSource do
  # One entry can have several outbox rows; marking must go by outbox_position,
  # never by entry id, or a later still-unsent snapshot would be dropped.
  it "persists sent state by outbox position so marking twice is harmless and a later generation of the same entry stays unsent" do
    now = Time.utc(2026, 4, 1, 12)
    base = {
      "id" => 501, "project_id" => 7, "user_id" => 9, "agent_id" => nil, "work_date" => Date.new(2026, 4, 1),
      "duration" => 60.0, "note" => "n", "bill_status" => "unbilled", "review_status" => "not_required",
      "locked" => false, "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
      "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
      "created_at" => now, "updated_at" => now, "company_id" => 3, "generation" => 1
    }
    positions = OutboxSnapshot.insert_all!(
      [base.merge("version" => 1), base.merge("version" => 2)], returning: %w[outbox_position]
    ).rows.flatten
    first, second = positions.sort

    described_class.new.mark_sent([first])
    expect { described_class.new.mark_sent([first]) }.not_to raise_error

    rows = described_class.new.unsent_after(0, 10)
    expect(rows.map { |row| row["outbox_position"] }).to eq([second])
    expect(rows.first["entry"]["version"]).to eq(2)
    expect(OutboxSnapshot.where(outbox_position: second).pick(:sent_at)).to be_nil
  end
end

require "rails_helper"

RSpec.describe Timekeeping::RelayOutboxSource do
  it "returns unsent outbox rows above the position in outbox_position order, across gaps, capped at the limit" do
    written_at = Time.utc(2026, 3, 2, 9)
    row = lambda do |position, entry_id|
      {
        "id" => entry_id, "project_id" => 5, "user_id" => 6, "agent_id" => nil, "work_date" => Date.new(2026, 3, 2),
        "duration" => 60.0, "note" => nil, "bill_status" => "unbilled", "review_status" => "not_required",
        "locked" => false, "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
        "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
        "created_at" => written_at, "updated_at" => written_at, "company_id" => 1, "version" => 1,
        "generation" => 1, "outbox_position" => position
      }
    end
    # Written out of order and with gaps, as a rolled-back write leaves them.
    OutboxSnapshot.insert_all!([row.call(12, 30), row.call(3, 10), row.call(7, 20)])

    source = described_class.new

    # "It delivers in `outbox_position` order."
    expect(source.unsent_after(0, 10).map { |item| item.fetch("outbox_position") }).to eq([3, 7, 12])
    expect(source.unsent_after(0, 10).map { |item| item.fetch("entry").fetch("id") }).to eq([10, 20, 30])
    expect(source.unsent_after(3, 1).map { |item| item.fetch("outbox_position") }).to eq([7])
    expect(source.unsent_after(12, 10)).to eq([])

    source.mark_sent([3])
    expect(source.unsent_after(0, 10).map { |item| item.fetch("outbox_position") }).to eq([7, 12])
  end
end
